 for i,j in pairs:
  for d in range(1,degree if i in cont else 2):
   for e in range(1,degree if j in cont else 2):
    if d+e<=degree:
     B.append(pol[d][:,i]*pol[e][:,j]); names.append([i,d,j,e])
 return np.array(B).T,names
