def hp(i,j,ki,kj,value):
 if i<j: add(("hp",i,j,float(ki),float(kj)),value)
 else: add(("hp",j,i,float(kj),float(ki)),value)
low=mu-scale
for n,v in zip(idx,cc):
 name=names[n]; kind=name[0]
 if kind=="const": add(("const",),v)
 elif kind=="lin":
  i=name[1]; add(("lin",i),v/scale[i]); add(("const",),-v*mu[i]/scale[i])
 elif kind=="hinge":
  i,k=name[1:]; add(("hinge",i,float(mu[i]+scale[i]*k)),v/scale[i])
 elif kind=="pair":
  i,j=name[1:]; value=v/(scale[i]*scale[j])
  pair(i,j,value); add(("lin",i),-value*mu[j]); add(("lin",j),-value*mu[i]); add(("const",),value*mu[i]*mu[j])
 else:
  i,j=name[1:]; value=v/(scale[i]*scale[j])
  hp(i,j,mu[i],low[j],2*value)
  add(("hinge",i,float(mu[i])),2*value*(low[j]-mu[j]))
  pair(i,j,-value)
  add(("lin",i),value*mu[j])
  add(("lin",j),v*(mu[i]/scale[i]-.5)/scale[j])
  add(("const",),-v*(mu[i]/scale[i]-.5)*mu[j]/scale[j])
raw={k:round(v,6) for k,v in raw.items() if abs(v)>0.0000005}
def rawpredict(Z):
 result=np.zeros(len(Z))
 for key,v in raw.items():
  kind=key[0]
  if kind=="const": result+=v
  elif kind=="lin": result+=v*Z[:,key[1]]
  elif kind=="hinge": result+=v*np.maximum(Z[:,key[1]]-key[2],0)
  elif kind=="pair": result+=v*Z[:,key[1]]*Z[:,key[2]]
  else: result+=v*np.maximum(Z[:,key[1]]-key[3],0)*np.maximum(Z[:,key[2]]-key[4],0)
 return result
