obj={"intercept":raw[("const",)],"terms":terms,"interactions":interactions}

print("nrawterms",len(raw),len(terms),len(interactions),"metrics",metrics(rawpredict(T)),"roundingmax",np.max(abs(rawpredict(T)-B[:,idx]@cc)))
